<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import {
  ArrowRight, BadgeCheck, BarChart3, Bell, Box, ChevronDown, ChevronLeft, ChevronRight,
  CircleUserRound, ClipboardList, Filter, Heart, LayoutDashboard, Menu, Package,
  Search, ShoppingBag, SlidersHorizontal, Sparkles, Truck, UserRound, X, Zap, Mail, Phone, MapPin, Send, MessageCircle, Cpu, Monitor, HardDrive, CheckCircle2, Info,
} from 'lucide-vue-next';
import { catalogBrands, catalogCategories, catalogGroups, catalogProducts, demoCart, demoOrders, type CatalogProduct } from '@shared/catalog';
type Product = CatalogProduct;
type CartLine = Product & { quantity: number };
const imageBase = '/manus-storage/';
const products: Product[] = catalogProducts;

const route = ref(window.location.pathname || '/');
const search = ref('');
const activeCategory = ref('Tất cả');
const activeCatalogGroup = ref('Laptop');
const categoryGroups = [...catalogGroups];
const activeBrand = ref('Tất cả');
const sortBy = ref('Nổi bật');
const showFilters = ref(false);
const showCart = ref(false);
const showProfile = ref(false);
const role = ref<'user' | 'admin'>((localStorage.getItem('nexa-role') as 'user' | 'admin') || 'user');
const cart = ref<CartLine[]>(JSON.parse(localStorage.getItem('nexa-cart') || JSON.stringify(demoCart)));
const toast = ref('');
const page = ref(1);
const pageSize = 4;
const priceBucket = ref('Tất cả');
const catalogLoading = ref(true);
const catalogError = ref('');
const orders = ref<any[]>(JSON.parse(localStorage.getItem('nexa-orders') || JSON.stringify(demoOrders)));
const adminTab = ref<'overview' | 'products' | 'categories' | 'inventory' | 'users' | 'orders'>('overview');
const adminSearch = ref('');
const showProductForm = ref(false);
const productDraft = ref({ name: '', brand: 'Nexa', price: 19990000, category: 'Văn phòng' });
const adminProducts = ref<Product[]>([...products]);
const adminCategories = ref(categoriesSeed());
const categoryDraft = ref('');
const contactForm = ref({ name: '', email: '', phone: '', message: '' });
const contactSent = ref(false);
const contactSending = ref(false);
const builder = ref({ usage: 'Gaming', cpu: 'Intel Core i7', gpu: 'RTX 4070', ram: '32GB RAM', storage: '1TB SSD', budget: '30 – 40 triệu' });
const builderPrices: Record<string, number> = { 'Intel Core i5': 5500000, 'Intel Core i7': 9500000, 'AMD Ryzen 7': 8200000, 'RTX 4060': 9500000, 'RTX 4070': 15500000, 'RTX 4080': 26500000, '16GB RAM': 1800000, '32GB RAM': 3200000, '64GB RAM': 6500000, '512GB SSD': 1600000, '1TB SSD': 2800000, '2TB SSD': 5200000 };
const builderTotal = computed(() => (builderPrices[builder.value.cpu] || 0) + (builderPrices[builder.value.gpu] || 0) + (builderPrices[builder.value.ram] || 0) + (builderPrices[builder.value.storage] || 0) + 4500000);
const builderCompatible = computed(() => builder.value.gpu === 'RTX 4080' && builder.value.ram === '16GB RAM' ? 'Nên nâng RAM lên 32GB để cân bằng cấu hình.' : 'Cấu hình đang cân bằng cho nhu cầu đã chọn.');
const categories = ['Tất cả', ...catalogCategories];
const brands = ['Tất cả', ...catalogBrands];
function categoriesSeed() { return [...catalogCategories].map((name, index) => ({ id: index + 1, name, products: products.filter(item => item.category === name).length })); }

const money = (value: number) => new Intl.NumberFormat('vi-VN').format(value) + ' ₫';
const navigate = (path: string) => { route.value = path; window.history.pushState({}, '', path); window.scrollTo({ top: 0, behavior: 'smooth' }); showProfile.value = false; };
const navigateGroup = (group: string) => { activeCatalogGroup.value = group; activeCategory.value = 'Tất cả'; activeBrand.value = 'Tất cả'; page.value = 1; navigate('/laptops'); };
const submitBuilder = () => { notify(`Đã lưu cấu hình ${builder.value.usage} khoảng ${money(builderTotal.value)}`); };
const submitContact = () => { if (!contactForm.value.name || !contactForm.value.email || !contactForm.value.message) { notify('Vui lòng điền tên, email và nội dung cần tư vấn'); return; } contactSending.value = true; window.setTimeout(() => { contactSending.value = false; contactSent.value = true; contactForm.value = { name: '', email: '', phone: '', message: '' }; notify('Tin nhắn đã được gửi đến đội ngũ NEXA'); }, 650); };
window.addEventListener('popstate', () => { route.value = window.location.pathname; });
const setRole = (next: 'user' | 'admin') => { role.value = next; localStorage.setItem('nexa-role', next); showProfile.value = false; navigate(next === 'admin' ? '/admin' : '/'); };
window.setTimeout(() => { catalogLoading.value = false; }, 420);
const persistCart = () => localStorage.setItem('nexa-cart', JSON.stringify(cart.value));
const notify = (message: string) => { toast.value = message; window.setTimeout(() => toast.value = '', 2600); };

const filteredProducts = computed(() => {
  let list = products.filter((item) => {
    const q = search.value.toLowerCase().trim();
    const matchesGroup = (item.group || 'Laptop') === activeCatalogGroup.value;
    const matchesSearch = !q || `${item.name} ${item.brand} ${item.specs.join(' ')}`.toLowerCase().includes(q);
    const matchesCategory = activeCategory.value === 'Tất cả' || item.category === activeCategory.value;
    const matchesBrand = activeBrand.value === 'Tất cả' || item.brand === activeBrand.value;
    const matchesPrice = priceBucket.value === 'Tất cả' || (priceBucket.value === 'under20' && item.price < 20000000) || (priceBucket.value === '20to30' && item.price >= 20000000 && item.price <= 30000000) || (priceBucket.value === 'over30' && item.price > 30000000);
    return matchesGroup && matchesSearch && matchesCategory && matchesBrand && matchesPrice;
  });
  if (sortBy.value === 'Giá thấp') list = [...list].sort((a, b) => a.price - b.price);
  if (sortBy.value === 'Giá cao') list = [...list].sort((a, b) => b.price - a.price);
  if (sortBy.value === 'Đánh giá') list = [...list].sort((a, b) => b.rating - a.rating);
  return list;
});
const pagedProducts = computed(() => filteredProducts.value.slice((page.value - 1) * pageSize, page.value * pageSize));
const pageCount = computed(() => Math.max(1, Math.ceil(filteredProducts.value.length / pageSize)));
const adminFilteredProducts = computed(() => adminProducts.value.filter((item) => `${item.name} ${item.brand} ${item.category}`.toLowerCase().includes(adminSearch.value.toLowerCase())));
const adminTitle = computed(() => ({ products: 'Quản lý sản phẩm', categories: 'Quản lý danh mục', inventory: 'Tồn kho', users: 'Người dùng', orders: 'Đơn hàng' } as Record<string, string>)[adminTab.value] || 'Tổng quan vận hành');
watch([search, activeCategory, activeBrand, priceBucket, sortBy], () => { page.value = 1; });
const cartCount = computed(() => cart.value.reduce((sum, item) => sum + item.quantity, 0));
const cartTotal = computed(() => cart.value.reduce((sum, item) => sum + item.price * item.quantity, 0));
const routeProduct = computed(() => { const id = Number(route.value.split('/').pop()); return products.find((item) => item.id === id) || products[0]; });
const addToCart = (product: Product) => { const existing = cart.value.find((item) => item.id === product.id); if (existing) existing.quantity += 1; else cart.value.push({ ...product, quantity: 1 }); persistCart(); notify(`${product.name} đã được thêm vào giỏ`); };
const updateQty = (id: number, delta: number) => { const item = cart.value.find((line) => line.id === id); if (!item) return; item.quantity += delta; if (item.quantity <= 0) cart.value = cart.value.filter((line) => line.id !== id); persistCart(); };
const removeFromCart = (id: number) => { cart.value = cart.value.filter((line) => line.id !== id); persistCart(); };
const checkout = () => { if (!cart.value.length) return; const order = { id: `NX-${Date.now().toString().slice(-6)}`, createdAt: new Date().toLocaleDateString('vi-VN'), items: cart.value.map(({ id, name, quantity, price }) => ({ id, name, quantity, price })), total: cartTotal.value, status: 'Đang xử lý' }; orders.value.unshift(order); localStorage.setItem('nexa-orders', JSON.stringify(orders.value)); cart.value = []; persistCart(); showCart.value = false; notify('Đơn hàng demo đã được ghi nhận'); navigate('/orders'); };
const saveProduct = () => { if (!productDraft.value.name.trim()) return; const draft = productDraft.value; adminProducts.value.unshift({ id: Date.now(), name: draft.name, brand: draft.brand, price: Number(draft.price), rating: 4.7, image: imageBase + 'ultra-01_c6203536.png', badge: 'Mới thêm', category: draft.category, specs: ['Core i7', '16GB RAM', '512GB SSD', '15.6” FHD'], stock: 10, tone: 'ice', group: activeCatalogGroup.value }); showProductForm.value = false; productDraft.value = { name: '', brand: 'Nexa', price: 19990000, category: 'Văn phòng' }; notify('Đã thêm sản phẩm vào catalog quản trị'); };
const removeAdminProduct = (id: number) => { adminProducts.value = adminProducts.value.filter((item) => item.id !== id); notify('Đã xóa sản phẩm khỏi danh sách demo'); };
const saveCategory = () => { const name = categoryDraft.value.trim(); if (!name) return; adminCategories.value.push({ id: Date.now(), name, products: 0 }); categoryDraft.value = ''; notify('Đã thêm danh mục vào hệ thống demo'); };
const removeCategory = (id: number) => { adminCategories.value = adminCategories.value.filter((item) => item.id !== id); notify('Đã xóa danh mục khỏi hệ thống demo'); };

const isAdmin = computed(() => route.value.startsWith('/admin'));
const productPage = computed(() => route.value === '/laptops' || route.value === '/');
const catalogGroupDescription = computed(() => activeCatalogGroup.value === 'Laptop' ? 'Cấu hình cân bằng, trải nghiệm rõ ràng, giá trị dài lâu.' : `Khám phá ${activeCatalogGroup.value.toLowerCase()} được tuyển chọn trong cùng một hệ sinh thái NEXA.`);
</script>

<template>
  <div class="app-shell" :class="{ 'admin-shell': isAdmin }">
    <div class="notice-bar">Miễn phí giao hàng đơn từ 5.000.000 ₫ · Bảo hành chính hãng · Đổi mới trong 7 ngày</div>

    <header v-if="!isAdmin" class="store-header">
      <div class="header-main container">
        <button class="mobile-menu icon-button"><Menu :size="21" /></button>
        <button class="brand-mark" @click="navigate('/')"><span>N</span><div><strong>NEXA</strong><small>COMPUTER STORE</small></div></button>
        <div class="search-wrap">
          <Search :size="18" />
          <input v-model="search" @keyup.enter="navigate('/laptops')" placeholder="Tìm laptop, thương hiệu hoặc cấu hình..." />
          <kbd>⌘ K</kbd>
        </div>
        <div class="header-actions">
          <button class="header-action" @click="showProfile = !showProfile"><CircleUserRound :size="21" /><span>Tài khoản<small>{{ role === 'admin' ? 'Quản trị viên' : 'Đăng nhập' }}</small></span></button>
          <button class="header-action heart-action"><Heart :size="21" /><span>Yêu thích<small>0 sản phẩm</small></span></button>
          <button class="cart-button" @click="showCart = true"><ShoppingBag :size="20" /><b>{{ cartCount }}</b><span>Giỏ hàng</span></button>
        </div>
      </div>
      <nav class="category-nav"><div class="container nav-inner"><button class="nav-category-trigger" @click="navigateGroup('Laptop')"><Menu :size="18" />Laptop</button><button @click="navigateGroup('PC')"><Monitor :size="16" /> PC</button><button @click="navigateGroup('Linh kiện')"><Cpu :size="16" /> Linh kiện</button><button @click="navigateGroup('Phần mềm')">Phần mềm</button><button @click="navigateGroup('Thiết bị văn phòng')">Thiết bị văn phòng</button><button @click="navigate('/builder')"><Zap :size="16" /> Tự tạo cấu hình</button><button @click="navigate('/contact')"><MessageCircle :size="16" /> Liên hệ</button><button @click="navigate('/orders')">Theo dõi đơn hàng</button><button class="admin-link" @click="setRole('admin')">Khu quản trị <ArrowRight :size="14" /></button></div></nav>
      <div v-if="showProfile" class="profile-popover"><div class="popover-title"><CircleUserRound :size="20" /><span>Không gian của bạn</span></div><p>{{ role === 'admin' ? 'Bạn đang xem với quyền quản trị.' : 'Đăng nhập để lưu giỏ hàng và đơn hàng.' }}</p><button v-if="role === 'user'" class="popover-button" @click="setRole('admin')">Xem khu quản trị demo</button><button v-else class="popover-button" @click="setRole('user')">Chuyển sang khách hàng</button></div>
    </header>

    <main v-if="!isAdmin">
      <section v-if="route === '/'" class="hero-section container">
        <div class="hero-copy"><p class="eyebrow"><Sparkles :size="15" /> BỘ SƯU TẬP MÙA THU 2026</p><h1>Công cụ mạnh.<br /><em>Ý tưởng rộng.</em></h1><p class="hero-text">Những chiếc laptop được tuyển chọn cho cách bạn học, làm việc và tạo ra điều khác biệt.</p><div class="hero-actions"><button class="primary-button" @click="navigate('/laptops')">Khám phá bộ sưu tập <ArrowRight :size="17" /></button><button class="text-button" @click="activeCategory = 'Gaming'; navigate('/laptops')">Xem laptop gaming <ChevronRight :size="16" /></button></div><div class="hero-proof"><div><strong>4.9/5</strong><span>đánh giá trung bình</span></div><div><strong>24h</strong><span>giao hàng nội thành</span></div><div><strong>7 ngày</strong><span>đổi mới tận tâm</span></div></div></div><div class="hero-art"><div class="art-glow"></div><div class="hero-card hero-card-back"></div><img :src="imageBase + 'gaming-01_fcf5102a.jpg'" alt="Laptop gaming NEXA" /><div class="art-caption"><span>01 / 04</span><strong>Forge 16 Studio</strong><small>Hiệu năng dành cho những khung hình lớn.</small></div><div class="art-dots"><i class="active"></i><i></i><i></i><i></i></div></div>
      </section>

      <section v-if="route === '/'" class="trust-strip"><div class="container trust-grid"><div><BadgeCheck :size="22" /><span><strong>Sản phẩm chính hãng</strong><small>Đầy đủ chứng từ và bảo hành</small></span></div><div><Truck :size="22" /><span><strong>Giao hàng toàn quốc</strong><small>Đóng gói kỹ, theo dõi dễ dàng</small></span></div><div><Zap :size="22" /><span><strong>Tư vấn đúng nhu cầu</strong><small>Không ép cấu hình, không nói quá</small></span></div><div><Box :size="22" /><span><strong>Đổi mới minh bạch</strong><small>Hỗ trợ nhanh khi sản phẩm lỗi</small></span></div></div></section>

      <section v-if="route === '/'" class="category-section container"><div class="section-heading"><div><p class="eyebrow">TÌM THEO CÁCH BẠN DÙNG</p><h2>Chọn đúng nhịp sống.</h2></div><button class="text-button" @click="navigate('/laptops')">Xem tất cả <ArrowRight :size="16" /></button></div><div class="category-grid"><button class="category-card category-card-dark" @click="activeCategory = 'Gaming'; navigate('/laptops')"><span>01 / GAMING</span><h3>Chơi lớn,<br />không giới hạn.</h3><img :src="imageBase + 'gaming-02_a2f2846b.jpg'" alt="Laptop gaming" /><ArrowRight :size="20" /></button><button class="category-card category-card-light" @click="activeCategory = 'Văn phòng'; navigate('/laptops')"><span>02 / WORK</span><h3>Nhẹ nhàng<br />mỗi ngày.</h3><img :src="imageBase + 'ultra-01_c6203536.png'" alt="Laptop văn phòng" /><ArrowRight :size="20" /></button><button class="category-card category-card-violet" @click="activeCategory = 'Đồ họa'; navigate('/laptops')"><span>03 / CREATE</span><h3>Ý tưởng<br />thành hình.</h3><img :src="imageBase + 'loq-01_65bdadbf.jpg'" alt="Laptop đồ họa" /><ArrowRight :size="20" /></button></div></section>

      <section v-if="route === '/' || route === '/laptops'" class="catalog-section container" :class="{ 'catalog-page': route === '/laptops' }"><div class="section-heading catalog-heading"><div><p class="eyebrow">NEXA SELECTS / {{ activeCatalogGroup.toUpperCase() }}</p><h2>{{ route === '/laptops' ? activeCatalogGroup + ' · Danh mục sản phẩm' : 'Những lựa chọn nổi bật.' }}</h2><p class="section-subtitle">{{ catalogGroupDescription }}</p></div><div class="catalog-tools"><button class="filter-toggle" @click="showFilters = !showFilters"><SlidersHorizontal :size="16" /> Bộ lọc</button><select v-model="sortBy"><option>Nổi bật</option><option>Giá thấp</option><option>Giá cao</option><option>Đánh giá</option></select></div></div><div class="catalog-layout"><aside class="filter-panel" :class="{ open: showFilters }"><div class="filter-head"><strong>Bộ lọc</strong><button @click="showFilters = false"><X :size="17" /></button></div><div class="filter-group"><p>Danh mục</p><button v-for="item in categories" :key="item" :class="{ selected: activeCategory === item }" @click="activeCategory = item">{{ item }} <span v-if="item === 'Tất cả'">{{ products.length }}</span></button></div><div class="filter-group"><p>Thương hiệu</p><button v-for="brand in brands" :key="brand" :class="{ selected: activeBrand === brand }" @click="activeBrand = brand">{{ brand }} <span v-if="brand !== 'Tất cả'">›</span></button></div><div class="filter-group"><p>Khoảng giá</p><label class="check-row"><input v-model="priceBucket" value="under20" type="radio" name="price" /> Dưới 20 triệu</label><label class="check-row"><input v-model="priceBucket" value="20to30" type="radio" name="price" /> 20 – 30 triệu</label><label class="check-row"><input v-model="priceBucket" value="over30" type="radio" name="price" /> Trên 30 triệu</label></div><button class="clear-filter" @click="activeCategory = 'Tất cả'; activeBrand = 'Tất cả'; search = ''">Xóa bộ lọc</button></aside><div class="product-area"><div v-if="catalogLoading" class="catalog-status"><span class="loading-ring"></span> Đang tải catalog...</div><div v-else-if="catalogError" class="catalog-status error-state"><strong>Không tải được catalog</strong><span>{{ catalogError }}</span></div><template v-else><div class="result-line"><span><strong>{{ filteredProducts.length }}</strong> sản phẩm phù hợp</span><span v-if="search">Kết quả cho “{{ search }}”</span></div><div v-if="!pagedProducts.length" class="catalog-status"><Search :size="22" /><strong>Không tìm thấy sản phẩm phù hợp</strong><span>Hãy thử bỏ bớt bộ lọc hoặc tìm bằng từ khóa khác.</span></div><div v-else class="product-grid"><article v-for="product in pagedProducts" :key="product.id" class="product-card"><div class="product-image" :class="product.tone" @click="navigate('/product/' + product.id)"><span class="product-badge">{{ product.badge }}</span><button class="wish-button" @click.stop="notify('Đã lưu vào danh sách yêu thích')"><Heart :size="17" /></button><img :src="product.image" :alt="product.name" /></div><div class="product-info"><p class="product-brand">{{ product.brand }} / {{ product.category }}</p><h3 @click="navigate('/product/' + product.id)">{{ product.name }}</h3><div class="spec-row"><span v-for="spec in product.specs" :key="spec">{{ spec }}</span></div><div class="product-detail-link"><button @click="navigate('/product/' + product.id)">Xem thông tin chi tiết <ArrowRight :size="15" /></button></div><div class="product-bottom"><div><strong>{{ money(product.price) }}</strong><del v-if="product.oldPrice">{{ money(product.oldPrice) }}</del></div><button class="add-button" @click="addToCart(product)"><ShoppingBag :size="17" /></button></div></div></article></div><div v-if="pagedProducts.length" class="pagination"><button :disabled="page === 1" @click="page--"><ChevronLeft :size="17" /></button><button v-for="n in pageCount" :key="n" :class="{ current: page === n }" @click="page = n">{{ n }}</button><button :disabled="page === pageCount" @click="page++"><ChevronRight :size="17" /></button></div></template></div></div></section>

      <section v-if="route === '/'" class="journal-section container"><div class="journal-note"><p class="eyebrow">NEXA JOURNAL</p><h2>Chọn máy<br /><em>cũng là chọn cách sống.</em></h2><p>Những ghi chú ngắn về công nghệ, cấu hình và cách tìm một thiết bị vừa vặn với bạn.</p><button class="text-button">Đọc tạp chí <ArrowRight :size="16" /></button></div><div class="journal-feature"><div class="journal-number">01</div><div><span>GUIDE / 06.09.2026</span><h3>RAM bao nhiêu là đủ cho một ngày làm việc hiện đại?</h3><p>Từ những tab trình duyệt đến những project đang dang dở, hãy bắt đầu từ cách bạn thực sự làm việc.</p><button class="text-button">Đọc bài viết <ArrowRight :size="16" /></button></div></div></section>
      <section v-if="route === '/builder'" class="builder-page container"><div class="page-intro"><p class="eyebrow"><Sparkles :size="15" /> NEXA CONFIG LAB</p><h1>Tự tạo cấu hình<br /><em>đúng nhu cầu.</em></h1><p>Chọn mục đích sử dụng và các thành phần chính. NEXA sẽ tổng hợp ngân sách, kiểm tra cân bằng và gợi ý bước tiếp theo.</p></div><form class="builder-layout" @submit.prevent="submitBuilder"><div class="builder-panel panel"><div class="builder-section"><label>Nhu cầu sử dụng<select v-model="builder.usage"><option>Gaming</option><option>Đồ họa</option><option>Làm việc</option><option>Học tập</option></select></label><label>Ngân sách dự kiến<select v-model="builder.budget"><option>Dưới 20 triệu</option><option>20 – 30 triệu</option><option>30 – 40 triệu</option><option>Trên 40 triệu</option></select></label></div><div class="builder-section"><label><span><Cpu :size="16" /> CPU</span><select v-model="builder.cpu"><option>Intel Core i5</option><option>Intel Core i7</option><option>AMD Ryzen 7</option></select></label><label><span><Monitor :size="16" /> GPU</span><select v-model="builder.gpu"><option>RTX 4060</option><option>RTX 4070</option><option>RTX 4080</option></select></label><label><span><HardDrive :size="16" /> RAM</span><select v-model="builder.ram"><option>16GB RAM</option><option>32GB RAM</option><option>64GB RAM</option></select></label><label><span><HardDrive :size="16" /> Lưu trữ</span><select v-model="builder.storage"><option>512GB SSD</option><option>1TB SSD</option><option>2TB SSD</option></select></label></div><button class="primary-button" type="submit">Lưu cấu hình <ArrowRight :size="17" /></button></div><aside class="builder-summary panel"><span class="panel-kicker">BẢN NHÁP CẤU HÌNH</span><h2>{{ builder.usage }}</h2><div class="builder-summary-row"><span>Ngân sách</span><strong>{{ builder.budget }}</strong></div><div class="builder-summary-row"><span>Ước tính linh kiện</span><strong>{{ money(builderTotal) }}</strong></div><div class="compatibility-note"><CheckCircle2 :size="18" /><span>{{ builderCompatible }}</span></div><button class="outline-button" type="button" @click="navigate('/contact')">Gửi cấu hình để được tư vấn <Send :size="16" /></button></aside></form></section>
      <section v-if="route === '/contact'" class="contact-page container"><div class="page-intro"><p class="eyebrow"><MessageCircle :size="15" /> NEXA SUPPORT</p><h1>Nói chuyện với<br /><em>đội ngũ của NEXA.</em></h1><p>Gửi nhu cầu, ngân sách hoặc cấu hình bạn đang cân nhắc. Chúng tôi sẽ phản hồi bằng một đề xuất rõ ràng, không vòng vo.</p><div class="contact-details"><div><Phone :size="18" /><span><strong>1800 6868</strong><small>08:00 – 22:00 mỗi ngày</small></span></div><div><Mail :size="18" /><span><strong>hello@nexa.store</strong><small>Phản hồi trong giờ làm việc</small></span></div><div><MapPin :size="18" /><span><strong>Showroom NEXA</strong><small>Quận 1, TP. Hồ Chí Minh</small></span></div></div></div><div class="contact-form-card panel"><div v-if="contactSent" class="success-state"><CheckCircle2 :size="34" /><h2>Đã nhận tin nhắn.</h2><p>Đội ngũ NEXA sẽ liên hệ lại với bạn trong thời gian sớm nhất.</p><button class="outline-button" @click="contactSent = false">Gửi tin nhắn khác</button></div><form v-else @submit.prevent="submitContact"><div class="form-row"><label>Họ và tên<input v-model="contactForm.name" placeholder="Nguyễn Văn A" /></label><label>Email<input v-model="contactForm.email" type="email" placeholder="you@example.com" /></label></div><div class="form-row"><label>Số điện thoại<input v-model="contactForm.phone" placeholder="09xx xxx xxx" /></label><label>Chủ đề<select><option>Tư vấn laptop</option><option>Tư vấn PC</option><option>Tự tạo cấu hình</option><option>Bảo hành và đơn hàng</option></select></label></div><label>Nội dung cần tư vấn<textarea v-model="contactForm.message" rows="6" placeholder="Bạn đang cần một thiết bị cho công việc gì?"></textarea></label><button class="primary-button" type="submit" :disabled="contactSending">{{ contactSending ? 'Đang gửi...' : 'Gửi tin nhắn' }} <Send :size="17" /></button></form></div></section>
      <section v-if="route === '/orders'" class="account-page container"><p class="eyebrow">TÀI KHOẢN</p><h1>Đơn hàng của bạn</h1><div v-if="!orders.length" class="empty-state"><ClipboardList :size="34" /><h3>Chưa có đơn hàng gần đây</h3><p>Đơn hàng demo sau khi checkout sẽ xuất hiện ở đây.</p><button class="primary-button" @click="navigate('/laptops')">Tiếp tục mua sắm <ArrowRight :size="17" /></button></div><div v-else class="orders-list"><article v-for="order in orders" :key="order.id" class="order-card"><div><span class="order-id">{{ order.id }}</span><strong>{{ order.createdAt }}</strong><small>{{ order.items.length }} sản phẩm · {{ order.status }}</small></div><div class="order-total"><strong>{{ money(order.total) }}</strong><button class="outline-button">Xem chi tiết</button></div></article></div></section>
      <section v-if="route.startsWith('/product/')" class="detail-page container"><button class="back-button" @click="navigate('/laptops')"><ChevronLeft :size="17" /> Quay lại danh sách</button><div class="detail-layout"><div class="detail-image"><span>{{ routeProduct.badge }}</span><img :src="routeProduct.image" :alt="routeProduct.name" /></div><div class="detail-content"><p class="product-brand">{{ routeProduct.brand }} / {{ routeProduct.category }}</p><h1>{{ routeProduct.name }}</h1><div class="detail-rating">★ {{ routeProduct.rating }} <span>Đánh giá từ khách hàng NEXA</span></div><div class="detail-price">{{ money(routeProduct.price) }} <del v-if="routeProduct.oldPrice">{{ money(routeProduct.oldPrice) }}</del></div><p class="detail-description">Một lựa chọn được cân bằng cho hiệu suất ổn định, màn hình đẹp và trải nghiệm sử dụng lâu dài.</p><div class="detail-specs"><div v-for="spec in routeProduct.specs" :key="spec"><BadgeCheck :size="16" />{{ spec }}</div></div><div class="detail-actions"><button class="primary-button" @click="addToCart(routeProduct)">Thêm vào giỏ <ShoppingBag :size="17" /></button><button class="outline-button" @click="notify('Đã gửi yêu cầu tư vấn')">Tư vấn cấu hình</button></div><div class="detail-note"><Truck :size="18" /><span>Giao nhanh trong 24h tại nội thành · Còn {{ routeProduct.stock }} sản phẩm</span></div></div></div></section>
      <footer class="store-footer"><div class="container footer-grid"><div><button class="brand-mark footer-brand" @click="navigate('/')"><span>N</span><div><strong>NEXA</strong><small>COMPUTER STORE</small></div></button><p>Thiết bị rõ ràng cho những ý tưởng lớn.</p></div><div><strong>Khám phá</strong><button @click="navigateGroup('Laptop')">Laptop</button><button @click="navigate('/builder')">Tự tạo cấu hình</button><button @click="navigate('/orders')">Theo dõi đơn hàng</button></div><div><strong>Hỗ trợ</strong><button @click="navigate('/contact')">Liên hệ và gửi tin nhắn</button><button @click="notify('Chính sách bảo hành đang được cập nhật')">Bảo hành</button><button @click="notify('Chính sách đổi mới đang được cập nhật')">Đổi mới 7 ngày</button></div><div><strong>Trụ sở</strong><span>Showroom NEXA, Quận 1</span><span>1800 6868</span><span>hello@nexa.store</span></div></div></footer>
    </main>

    <main v-else class="admin-main"><aside class="admin-sidebar"><button class="admin-brand" @click="navigate('/admin')"><span>N</span><div><strong>NEXA</strong><small>ADMIN SPACE</small></div></button><div class="admin-profile"><div class="avatar">AD</div><div><strong>Alex Designer</strong><small>Quản trị viên</small></div></div><nav><p>QUẢN LÝ</p><button :class="{ active: adminTab === 'overview' }" @click="adminTab = 'overview'"><LayoutDashboard :size="18" /> Tổng quan</button><button :class="{ active: adminTab === 'products' }" @click="adminTab = 'products'"><Package :size="18" /> Sản phẩm <em>{{ adminProducts.length }}</em></button><button :class="{ active: adminTab === 'categories' }" @click="adminTab = 'categories'"><Box :size="18" /> Danh mục <em>{{ adminCategories.length }}</em></button><button :class="{ active: adminTab === 'inventory' }" @click="adminTab = 'inventory'"><Box :size="18" /> Tồn kho <em class="warning">3</em></button><button :class="{ active: adminTab === 'orders' }" @click="adminTab = 'orders'"><ClipboardList :size="18" /> Đơn hàng <em>{{ orders.length }}</em></button><button :class="{ active: adminTab === 'users' }" @click="adminTab = 'users'"><UserRound :size="18" /> Người dùng</button><p>HỆ THỐNG</p><button @click="notify('Báo cáo sẽ được bổ sung sau khi kết nối dữ liệu thật')"><BarChart3 :size="18" /> Báo cáo</button><button @click="notify('Không có thông báo mới')"><Bell :size="18" /> Thông báo</button></nav><button class="back-store" @click="setRole('user')"><ArrowRight :size="17" /> Về storefront</button></aside><section class="admin-content"><div class="admin-topbar"><div><p class="eyebrow">THỨ HAI, 14 THÁNG 9, 2026</p><h1>{{ adminTitle }}</h1></div><div class="admin-actions"><button class="icon-button"><Search :size="19" /></button><button class="icon-button notification-dot"><Bell :size="19" /></button><button class="admin-user">AD <ChevronDown :size="15" /></button></div></div><div v-if="adminTab !== 'overview'" class="admin-management panel"><div class="management-head"><div><span class="panel-kicker">DỮ LIỆU VẬN HÀNH</span><h2>{{ adminTitle }}</h2></div><div class="management-tools"><input v-model="adminSearch" placeholder="Tìm trong danh sách..." /><button v-if="adminTab === 'products'" class="primary-button compact" @click="showProductForm = !showProductForm">{{ showProductForm ? 'Đóng form' : 'Thêm sản phẩm' }}</button></div></div><div v-if="adminTab === 'products'" class="management-body"><form v-if="showProductForm" class="product-form" @submit.prevent="saveProduct"><input v-model="productDraft.name" required placeholder="Tên sản phẩm" /><input v-model="productDraft.brand" placeholder="Thương hiệu" /><input v-model.number="productDraft.price" type="number" min="0" placeholder="Giá bán" /><select v-model="productDraft.category"><option v-for="category in categories.slice(1)" :key="category">{{ category }}</option></select><button class="primary-button compact" type="submit">Lưu sản phẩm</button></form><table><thead><tr><th>SẢN PHẨM</th><th>THƯƠNG HIỆU</th><th>DANH MỤC</th><th>GIÁ</th><th>TỒN</th><th></th></tr></thead><tbody><tr v-for="product in adminFilteredProducts" :key="product.id"><td><strong>{{ product.name }}</strong></td><td>{{ product.brand }}</td><td>{{ product.category }}</td><td>{{ money(product.price) }}</td><td>{{ product.stock }}</td><td><button class="table-action" @click="removeAdminProduct(product.id)">Xóa</button></td></tr></tbody></table></div><div v-else-if="adminTab === 'categories'" class="management-body"><form class="product-form category-form" @submit.prevent="saveCategory"><input v-model="categoryDraft" required placeholder="Tên danh mục mới" /><button class="primary-button compact" type="submit">Thêm danh mục</button></form><table><thead><tr><th>DANH MỤC</th><th>SỐ SẢN PHẨM</th><th>TRẠNG THÁI</th><th></th></tr></thead><tbody><tr v-for="category in adminCategories" :key="category.id"><td><strong>{{ category.name }}</strong></td><td>{{ category.products }}</td><td><span class="status delivered">Đang hoạt động</span></td><td><button class="table-action" @click="removeCategory(category.id)">Xóa</button></td></tr></tbody></table></div><div v-else-if="adminTab === 'inventory'" class="management-body"><table><thead><tr><th>SẢN PHẨM</th><th>SKU</th><th>TỒN KHO</th><th>NGƯỠNG</th><th>TRẠNG THÁI</th></tr></thead><tbody><tr v-for="product in adminProducts" :key="product.id"><td><strong>{{ product.name }}</strong></td><td>NX-{{ product.id }}</td><td>{{ product.stock }}</td><td>5</td><td><span :class="['status', product.stock <= 5 ? 'pending' : 'delivered']">{{ product.stock <= 5 ? 'Cần nhập' : 'Ổn định' }}</span></td></tr></tbody></table></div><div v-else-if="adminTab === 'orders'" class="management-body"><table><thead><tr><th>MÃ ĐƠN</th><th>NGÀY TẠO</th><th>SẢN PHẨM</th><th>GIÁ TRỊ</th><th>TRẠNG THÁI</th></tr></thead><tbody><tr v-for="order in orders" :key="order.id"><td><strong>{{ order.id }}</strong></td><td>{{ order.createdAt }}</td><td>{{ order.items.length }} sản phẩm</td><td>{{ money(order.total) }}</td><td><span class="status processing">{{ order.status }}</span></td></tr><tr v-if="!orders.length"><td colspan="5" class="empty-cell">Chưa có đơn hàng trong dữ liệu demo.</td></tr></tbody></table></div><div v-else-if="adminTab === 'users'" class="management-body"><table><thead><tr><th>NGƯỜI DÙNG</th><th>EMAIL</th><th>VAI TRÒ</th><th>TRẠNG THÁI</th></tr></thead><tbody><tr><td><strong>Người dùng demo</strong></td><td>user@nexa.store</td><td>Khách hàng</td><td><span class="status delivered">Đang hoạt động</span></td></tr><tr><td><strong>Alex Designer</strong></td><td>admin@nexa.store</td><td>Quản trị viên</td><td><span class="status delivered">Đang hoạt động</span></td></tr></tbody></table></div><div v-else class="management-body"><div class="category-admin-grid"><button v-for="category in categories.slice(1)" :key="category" class="category-admin-card" @click="adminSearch = category; adminTab = 'products'"><Package :size="20" /><strong>{{ category }}</strong><span>{{ adminProducts.filter(item => item.category === category).length }} sản phẩm</span></button></div></div></div><div v-if="adminTab === 'overview'" class="admin-kpis"><div class="kpi-card"><span>Doanh thu tháng này</span><strong>428,6 triệu ₫</strong><small class="positive">+18,4% <span>so với tháng trước</span></small><div class="sparkline blue"></div></div><div class="kpi-card"><span>Đơn hàng mới</span><strong>86</strong><small class="positive">+12,8% <span>trong 30 ngày</span></small><div class="sparkline green"></div></div><div class="kpi-card"><span>Giá trị đơn trung bình</span><strong>14,8 triệu ₫</strong><small class="neutral">Ổn định <span>so với tháng trước</span></small><div class="sparkline purple"></div></div><div class="kpi-card"><span>Tồn kho cảnh báo</span><strong>03</strong><small class="negative">Cần xử lý <span>trong hôm nay</span></small><div class="sparkline red"></div></div></div><div class="admin-grid"><div class="panel chart-panel"><div class="panel-head"><div><span class="panel-kicker">TỔNG QUAN DOANH THU</span><h2>Doanh thu theo thời gian</h2></div><select><option>30 ngày qua</option><option>7 ngày qua</option></select></div><div class="chart"><div class="chart-y"><span>60M</span><span>40M</span><span>20M</span><span>0</span></div><div class="chart-body"><div class="chart-grid-lines"><i></i><i></i><i></i><i></i></div><svg viewBox="0 0 680 220" preserveAspectRatio="none"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#68a7ff" stop-opacity=".30"/><stop offset="100%" stop-color="#68a7ff" stop-opacity="0"/></linearGradient></defs><path d="M0 180 C45 170 50 150 94 161 S140 141 175 146 S221 116 265 130 S310 92 350 112 S400 82 438 94 S478 72 520 88 S560 36 600 55 S645 28 680 42 L680 220 L0 220Z" fill="url(#area)"/><path d="M0 180 C45 170 50 150 94 161 S140 141 175 146 S221 116 265 130 S310 92 350 112 S400 82 438 94 S478 72 520 88 S560 36 600 55 S645 28 680 42" fill="none" stroke="#3178f6" stroke-width="3" stroke-linecap="round"/></svg><div class="chart-x"><span>18/08</span><span>25/08</span><span>01/09</span><span>08/09</span><span>14/09</span></div></div></div></div><div class="panel quick-panel"><div class="panel-head"><div><span class="panel-kicker">CẦN CHÚ Ý</span><h2>Tác vụ nhanh</h2></div></div><div class="quick-list"><button><span class="quick-icon amber">!</span><span><strong>03 sản phẩm tồn thấp</strong><small>Cần nhập thêm hàng</small></span><ArrowRight :size="16" /></button><button><span class="quick-icon blue">↗</span><span><strong>08 đơn đang chờ xử lý</strong><small>Cập nhật trạng thái</small></span><ArrowRight :size="16" /></button><button><span class="quick-icon purple">?</span><span><strong>05 yêu cầu tư vấn mới</strong><small>Phản hồi khách hàng</small></span><ArrowRight :size="16" /></button></div></div></div><div class="panel table-panel"><div class="panel-head"><div><span class="panel-kicker">GIAO DỊCH GẦN NHẤT</span><h2>Đơn hàng mới</h2></div><button class="text-button">Xem tất cả <ArrowRight :size="16" /></button></div><table><thead><tr><th>MÃ ĐƠN</th><th>KHÁCH HÀNG</th><th>SẢN PHẨM</th><th>GIÁ TRỊ</th><th>TRẠNG THÁI</th></tr></thead><tbody><tr><td><strong>#NX-240914</strong></td><td><span class="customer-cell"><span class="mini-avatar pink">NL</span>Ngọc Linh</span></td><td>Forge 16 Studio</td><td><strong>34.990.000 ₫</strong></td><td><span class="status processing">Đang xử lý</span></td></tr><tr><td><strong>#NX-240913</strong></td><td><span class="customer-cell"><span class="mini-avatar green">MT</span>Minh Trí</span></td><td>Lumen Air 14 Pro</td><td><strong>24.990.000 ₫</strong></td><td><span class="status delivered">Đã giao</span></td></tr><tr><td><strong>#NX-240912</strong></td><td><span class="customer-cell"><span class="mini-avatar blue">HA</span>Hà Anh</span></td><td>Apex Battle 17</td><td><strong>28.990.000 ₫</strong></td><td><span class="status pending">Chờ thanh toán</span></td></tr></tbody></table></div></section></main>

    <aside v-if="showCart" class="cart-overlay" @click.self="showCart = false"><div class="cart-drawer"><div class="drawer-head"><div><p class="eyebrow">NEXA BAG</p><h2>Giỏ hàng <small>({{ cartCount }})</small></h2></div><button class="icon-button" @click="showCart = false"><X :size="20" /></button></div><div v-if="cart.length" class="cart-lines"><div v-for="item in cart" :key="item.id" class="cart-line"><img :src="item.image" :alt="item.name" /><div><strong>{{ item.name }}</strong><small>{{ money(item.price) }}</small><div class="qty"><button @click="updateQty(item.id, -1)">−</button><span>{{ item.quantity }}</span><button @click="updateQty(item.id, 1)">+</button><button class="remove" @click="removeFromCart(item.id)">Xóa</button></div></div></div></div><div v-else class="cart-empty"><ShoppingBag :size="30" /><h3>Chiếc túi đang trống</h3><p>Thêm một lựa chọn phù hợp để bắt đầu.</p><button class="primary-button" @click="showCart = false; navigate('/laptops')">Khám phá laptop</button></div><div v-if="cart.length" class="cart-footer"><div><span>Tạm tính</span><strong>{{ money(cartTotal) }}</strong></div><button class="primary-button" @click="checkout">Đặt hàng demo <ArrowRight :size="17" /></button><small>Phí vận chuyển sẽ được tính ở bước tiếp theo.</small></div></div></aside>
    <div v-if="toast" class="toast"><BadgeCheck :size="18" /> {{ toast }}</div>
  </div>
</template>
